    surface-container-highest: #303632;
    background: #0f1511;
    foreground: #dfe4dd;
}


configuration{
	drun-display-format: "{icon} {name}";
	show-icons: true;
	display-drun: "";
	window-format: "{c}: {t}";
}

window {
    width: 600px;
    border: 2px;
    border-color: @primary-container;
    border-radius: 18px;
    background-color: @background;
    text-color: @foreground;
}

mainbox {
    padding: 20px;
    spacing: 15px;
    background-color: @background;
}

inputbar {
    padding: 12px;
    border-radius: 12px;

    background-color: @background;
    text-color: @foreground;
}

prompt {
    padding: 0 10px 0 0;
    text-color: @foreground;
}

entry {
    text-color: @foreground;
}

listview {
    spacing: 6px;
    lines: 8;
    columns: 1;
    scrollbar: false;
    background-color: @background;
}

element {
    padding: 10px 14px;
    border-radius: 10px;

    background-color: transparent;
    text-color: @foreground;
}

element-text {
    text-color: inherit;
}

element-icon {
    size: 24px;
    padding: 0 10px 0 0;
}

element selected {
        text-color: @background;
        background-color: @primary-container;

}
element alternate active {
        text-color: @background;
        background-color: @primary-container;

}

element selected element-text {
    text-color: inherit;
}

element selected element-icon {
    text-color: inherit;
}

message {
    padding: 10px;
    text-color: @foreground;
}

error-message {
    text-color: @error;
}








element alternate {
    background-color: @background;
    text-color: @on-surface;
}

element urgent {
    background-color: @error-container;
    text-color: @on-error-container;
}

element active {
    background-color: @primary-container;
    text-color: @on-primary-container;
}

element selected {
    background-color: @primary-container;
    text-color: @on-primary-container;
}

element selected normal {
    background-color: @primary-container;
    text-color: @on-primary-container;
}

